SELECT RULE_ID AS "ruleId", RULE_NAME AS "ruleName", COST_CENTER_ID AS "costCenterId", SOURCE_ACCOUNT AS "sourceAccount", COLLECTION_METHOD AS "collectionMethod", COLLECTION_TYPE AS "collectionType", RULE_DESCRIPTION AS "ruleDescription", IS_ENABLED AS "isEnabled", PRIORITY AS "priority", CREATE_TIME AS "createTime" FROM TBL_COST_COLLECTION_RULE WHERE BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId}
AND COST_CENTER_ID = #{costCenterId}
ORDER BY PRIORITY ASC, CREATE_TIME DESC

SELECT COUNT(1)
FROM TBL_COST_COLLECTION_RULE
WHERE RULE_NAME = #{ruleName}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}

      AND RULE_ID != #{ruleId}
